import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

depthwise_conv2d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void depthwise_conv2d_kernel(
    const int n,
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int channels,    // also equals out_channels for depthwise
    const int height_in,
    const int width_in,
    const int kernel_size,
    const int stride,
    const int padding,
    const bool has_bias
) {
    // Each thread corresponds to one element in the output tensor
    // Decode the linear index into (batch, channel, out_row, out_col)
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    if (idx >= n) return;

    int out_area = height_in * width_in;  // not final output area, just used for indexing
    // but let's decode carefully with the final out_h/out_w
    // We'll compute them from kernel size, stride, padding
    int out_h = (height_in + 2 * padding - kernel_size) / stride + 1;
    int out_w = (width_in  + 2 * padding - kernel_size) / stride + 1;

    int batch = idx / (channels * out_h * out_w);
    int idx2 = idx % (channels * out_h * out_w);
    int c = idx2 / (out_h * out_w);
    int idx3 = idx2 % (out_h * out_w);
    int out_row = idx3 / out_w;
    int out_col = idx3 % out_w;

    // Compute convolution
    float val = 0.0f;
    int kernel_rad = kernel_size / 2; // not used explicitly if we do standard indexing

    for (int i = 0; i < kernel_size; i++) {
        for (int j = 0; j < kernel_size; j++) {
            int in_row = out_row * stride - padding + i;
            int in_col = out_col * stride - padding + j;
            if (in_row >= 0 && in_row < height_in && in_col >= 0 && in_col < width_in) {
                // input index: (batch, c, in_row, in_col)
                // weight index: (c, 1, i, j)
                int in_idx = ((batch * channels + c) * height_in + in_row) * width_in + in_col;
                int w_idx = ((c * 1 + 0) * kernel_size + i) * kernel_size + j;
                val += input[in_idx] * weight[w_idx];
            }
        }
    }

    if (has_bias) {
        val += bias[c];
    }

    // output index: (batch, c, out_row, out_col)
    int out_idx = ((batch * channels + c) * out_h + out_row) * out_w + out_col;
    output[out_idx] = val;
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding
) {
    // Expect input of shape [B, C, H, W], weight of shape [C, 1, K, K]
    // bias of shape [C], or None
    TORCH_CHECK(input.dim() == 4, "Input must be 4D [B, C, H, W]");
    TORCH_CHECK(weight.dim() == 4, "Weight must be 4D [C, 1, K, K]");
    auto B = input.size(0);
    auto C = input.size(1);
    auto H_in = input.size(2);
    auto W_in = input.size(3);
    auto K = weight.size(2);

    // Output shape
    int H_out = (int)((H_in + 2 * padding - K) / stride) + 1;
    int W_out = (int)((W_in + 2 * padding - K) / stride) + 1;

    TORCH_CHECK(H_out > 0 && W_out > 0, "Invalid output size, check kernel/padding/stride.");

    // Create output tensor
    auto options = input.options();
    auto out = torch::zeros({B, C, H_out, W_out}, options);

    // Flatten for kernel indexing
    int total = B * C * H_out * W_out;

    bool has_bias = (bias.defined() && bias.numel() > 0);

    const int blockSize = 256;
    const int gridSize = (total + blockSize - 1) / blockSize;

    depthwise_conv2d_kernel<<<gridSize, blockSize>>>(
        total,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        out.data_ptr<float>(),
        B, C, H_in, W_in, K,
        stride, padding,
        has_bias
    );

    // Ensure CUDA kernel errors are caught
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "Depthwise conv2d kernel error: ", cudaGetErrorString(err));

    return out;
}
""";

depthwise_conv2d_cpp_source = r"""
torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding
);
""";

depthwise_conv2d = load_inline(
    name="depthwise_conv2d",
    cpp_sources=depthwise_conv2d_cpp_source,
    cuda_sources=depthwise_conv2d_source,
    functions=["depthwise_conv2d_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model using a custom CUDA depthwise conv2d kernel.
    Expects out_channels == in_channels for true 'depthwise' operation.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        # For depthwise conv with groups=in_channels, usually out_channels is a multiple of in_channels.
        # Here we assume out_channels == in_channels for a 1:1 channel mapping in the custom kernel.
        self.weight = nn.Parameter(
            torch.randn(out_channels, 1, kernel_size, kernel_size)
        ) 
        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return depthwise_conv2d.depthwise_conv2d_cuda(
            x, self.weight,
            self.bias if self.bias is not None else torch.tensor([]).to(x.device),
            self.stride,
            self.padding,
        )
